-- ============================================================
-- 外研社七上 s5 阅读灌库(junior_reading)
-- publisher='junior_fltrp' · volume='wy7A' · grade=7 · 7 篇 · 每篇 5 题(内联 questions jsonb)
-- 幂等:按 (publisher, volume) 先删后插,可安全重跑。Aaron service role 跑。
-- id / source_key 不预生成:DB 自动给 id,前端运行时拼 junior_reading_passage_<id>(module 裸 reading)。
-- 阅读原文全改写(同话题·同语言点·内容全新·8-gram 重合<8),无版权原文入库。
-- ============================================================
BEGIN;

-- 依赖(Phase1 迁移已加):junior_reading.publisher 列。本脚本不改 schema。

-- 1) 幂等删除本册阅读
DELETE FROM public.junior_reading WHERE publisher='junior_fltrp' AND volume='wy7A';

-- 2) 插入 7 篇(不写 id,DB 自动生成)
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'Starter', 'My new school', 'Today is my first week at Green Hill Junior High School. Everything here is new and exciting. There is a big library next to our classroom. It has thousands of books, and it is always quiet. There are two playgrounds, too. One is for basketball, and the other is for football. The playgrounds are large and green. My classroom is on the second floor. There are forty desks in it. My desk is near the window, so I can see the tall trees outside. My new classmates are friendly, and my teacher, Ms Wu, is kind and patient. "Welcome to your new school," she says. "There are many clubs here. You can join any of them." There is a music club, an art club and a science club. I am going to join the art club. I really like my new school!', '新学期·我的新学校', 142, 1, '[{"q": "Where is the library?", "answer": "B", "options": ["On the second floor.", "Next to the writer''s classroom.", "Near the two playgrounds.", "Outside the school gate."], "explanation": "原文 \"There is a big library next to our classroom.\""}, {"q": "Which club will the writer join?", "answer": "C", "options": ["The music club.", "The science club.", "The art club.", "The football club."], "explanation": "原文 \"I am going to join the art club.\""}, {"q": "What is the passage mainly about?", "answer": "A", "options": ["The writer''s new school and first week.", "How to play basketball.", "The writer''s favourite book.", "A trip to the library."], "explanation": "全文围绕作者初到新学校、介绍校园与感受。"}, {"q": "How does the writer probably feel about the new school?", "answer": "B", "options": ["Bored and tired.", "Happy and excited.", "Angry and sad.", "Afraid and lonely."], "explanation": "\"new and exciting\"、\"I really like my new school\" 等语气可推断愉快兴奋。"}, {"q": "\"My new classmates are friendly\" means they are ____.", "answer": "A", "options": ["kind and easy to talk to", "tall and strong", "busy and tired", "quiet and shy"], "explanation": "friendly = 友好的,易相处。"}]'::jsonb, '[{"word": "patient", "cn": "有耐心的"}, {"word": "club", "cn": "社团,俱乐部"}, {"word": "floor", "cn": "楼层"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U1', 'My first day', 'It is my first day at junior high school. I sit near the window with my new classmate, Ben. Our maths teacher, Mr Lee, comes in and smiles at us. "Good morning, everyone. Here is an easy question," he says. He writes some numbers on the board. "Who knows the answer?" Nobody puts up a hand. The room is very quiet. My heart beats fast. I think I know it, but I am not sure. Is my answer right? What if it is wrong? Ben looks at me. "You can try. It is OK to be wrong," he says. So I raise my hand. "Twelve," I say. My voice is small. "That is right! Well done," Mr Lee says. "This is your first lesson here: do not be afraid to try. In junior high, we learn from our mistakes." I smile at Ben. It really is a good first lesson.', '新学期·初中第一课', 150, 1, '[{"q": "Who helps the writer feel brave enough to answer?", "answer": "C", "options": ["Mr Lee, the maths teacher.", "A student near the door.", "Ben, the writer''s classmate.", "The writer''s mother."], "explanation": "Ben 说 \"You can try. It is OK to be wrong\",鼓励作者举手。"}, {"q": "What does Mr Lee write on the board?", "answer": "A", "options": ["Some numbers.", "A long sentence.", "The writer''s name.", "A famous saying."], "explanation": "原文 \"He writes some numbers on the board.\""}, {"q": "What is the best main idea of the passage?", "answer": "B", "options": ["Maths is the hardest subject.", "Don''t be afraid to try, even if you may be wrong.", "The first day of school is boring.", "Teachers always ask easy questions."], "explanation": "Mr Lee 的话点题:\"do not be afraid to try... we learn from our mistakes.\""}, {"q": "Why does the writer''s heart beat fast before answering?", "answer": "D", "options": ["Because the room is too hot.", "Because he is late for class.", "Because he does not know the answer at all.", "Because he is nervous about answering in front of everyone."], "explanation": "作者知道答案却不确定、怕答错(\"I am not sure... What if it is wrong?\"),紧张。文中未直说,靠推断。"}, {"q": "In the passage, \"My voice is small\" means the writer speaks ____.", "answer": "A", "options": ["quietly and shyly", "loudly and clearly", "quickly and angrily", "slowly and proudly"], "explanation": "紧张、不自信的语境下 \"voice is small\" = 声音小、怯生生地说。"}]'::jsonb, '[{"word": "classmate", "cn": "同班同学"}, {"word": "beat", "cn": "(心)跳动"}, {"word": "afraid", "cn": "害怕的"}, {"word": "raise", "cn": "举起"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U2', 'Music together', 'My name is Kevin. I love music. I play the drums in my school band. Every weekend, we practise in the music room. My friends and I like modern pop songs. My aunt loves music, too, but she likes old Chinese music. She plays the guzheng at home. Her music sounds soft and beautiful. Sometimes she teaches me a few notes. One day, our town has a small concert. I have an idea. "Aunt, let''s play together!" I say. She smiles and agrees. We practise every evening for two weeks. My drums are fast and strong. Her guzheng is slow and sweet. At first, the two sounds do not match. But we try again and again, and slowly they become one. On the concert day, everyone claps for us. Old music and new music make people happy together.', '音乐·新旧结合', 139, 1, '[{"q": "What instrument does Kevin play?", "answer": "A", "options": ["The drums.", "The guzheng.", "The guitar.", "The erhu."], "explanation": "原文 \"I play the drums in my school band.\""}, {"q": "When do Kevin and his aunt practise for the concert?", "answer": "C", "options": ["Every morning.", "Only at weekends.", "Every evening for two weeks.", "Once a month."], "explanation": "原文 \"We practise every evening for two weeks.\""}, {"q": "What is the best main idea of the passage?", "answer": "B", "options": ["Kevin''s aunt is a famous player.", "Old music and new music can come together and bring joy.", "Drums are better than the guzheng.", "A concert is held in the town every year."], "explanation": "末句点题:新旧音乐结合让人快乐。"}, {"q": "Why don''t the two sounds match at first?", "answer": "D", "options": ["Because Kevin plays too quietly.", "Because his aunt is angry.", "Because the music room is too small.", "Because the drums and the guzheng have very different styles."], "explanation": "drums 快而强、guzheng 慢而柔,风格不同,故起初不合;文中未直说,靠推断。"}, {"q": "\"Everyone claps for us\" means the people ____.", "answer": "A", "options": ["hit their hands together to show they like it", "walk away quietly", "fall asleep", "sing a new song"], "explanation": "clap = 鼓掌。"}]'::jsonb, '[{"word": "band", "cn": "乐队"}, {"word": "note", "cn": "音符"}, {"word": "match", "cn": "相配,匹配"}, {"word": "clap", "cn": "鼓掌"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U3', 'Grandpa''s silent love', 'My grandpa is a quiet man. He never says "I love you." But I can feel my grandpa''s love in many small things. Every morning, he cooks my breakfast. My favourite egg is always on my plate. On cold days, he puts my sister''s gloves and my coat by the door. He checks the air in my bike''s tyres before I go to school. Last winter, my mother''s hands were busy with work. So Grandpa quietly took care of the whole family''s dinner every night. He never asked for a "thank you". On my birthday, there is never a big party, but a bowl of long noodles is always ready — that is Grandpa''s quiet gift. One evening, I saw Grandpa mending my old schoolbag. His hands were slow, but his face was calm and happy. My eyes felt wet. My grandpa''s words are few. He gives no hugs and no kisses. But his love is real, and I feel it every single day, warm and strong.', '家庭·沉默的爱', 173, 1, '[{"q": "What does Grandpa do every morning?", "answer": "A", "options": ["He cooks the writer''s breakfast.", "He mends the schoolbag.", "He drives the writer to school.", "He buys new gloves."], "explanation": "原文 \"Every morning, he cooks my breakfast.\""}, {"q": "Who took care of the family''s dinner last winter?", "answer": "C", "options": ["The writer''s mother.", "The writer''s sister.", "Grandpa.", "The writer."], "explanation": "原文 \"So Grandpa quietly took care of the whole family''s dinner every night.\""}, {"q": "What is the main idea of the passage?", "answer": "B", "options": ["Grandpa is a good cook.", "Grandpa shows his love through actions, not words.", "The writer''s family is very busy.", "Winter is a hard season."], "explanation": "全文用小事说明爷爷用行动而非言语表达爱。"}, {"q": "Why did the writer''s eyes feel wet?", "answer": "D", "options": ["Because the room was cold.", "Because the schoolbag was broken.", "Because Grandpa was ill.", "Because the writer was moved by Grandpa''s quiet care."], "explanation": "看到爷爷默默补书包而感动;文中未直说,靠推断。"}, {"q": "\"Grandpa mending my old schoolbag\" — \"mending\" means ____.", "answer": "A", "options": ["repairing", "washing", "buying", "throwing away"], "explanation": "mend = 修补。"}]'::jsonb, '[{"word": "mend", "cn": "修补"}, {"word": "calm", "cn": "平静的"}, {"word": "gloves", "cn": "手套"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U4', 'An unusual Spring Festival', 'This year, our Spring Festival is unusual. We have a guest — Tom, a new classmate from Canada. It is his first Chinese New Year. My family always clean the house before the festival. We usually put red couplets on the door. This year, Tom helps us. He often makes mistakes, but he never stops smiling. On New Year''s Eve, my grandma cooks a big meal. We always eat dumplings at this time. "Why dumplings?" Tom asks. "Their shape is like old Chinese gold," my dad says. "They stand for good luck." Before the meal, we usually give red packets to the children. Tom often forgets the lucky words, but my grandma always helps him. Tom has never made dumplings before. His first one looks very funny, but he is proud of it. We sometimes drop the dumplings into the water too fast, and everyone laughs. At midnight, we watch the fireworks together. Tom says, "I never knew a festival could be so warm." This is the best Spring Festival for all of us.', '节日·不寻常的春节', 174, 1, '[{"q": "Where is Tom from?", "answer": "B", "options": ["China.", "Canada.", "Australia.", "America."], "explanation": "原文 \"Tom, a new classmate from Canada.\""}, {"q": "What does the family eat on New Year''s Eve?", "answer": "A", "options": ["Dumplings.", "A lion''s head meatball.", "Mooncakes.", "Fish and rice."], "explanation": "原文 \"We always eat dumplings at this time.\""}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["How to make dumplings.", "Tom is good at Chinese.", "Sharing the Spring Festival with a foreign friend makes it warm and special.", "The writer''s family is very rich."], "explanation": "全文围绕与外国朋友共度春节、氛围温暖。"}, {"q": "Why does the writer think this Spring Festival is unusual?", "answer": "D", "options": ["Because the family moves to a new house.", "Because they eat new food.", "Because it is very cold.", "Because a foreign friend joins the family for the first time."], "explanation": "不寻常在于第一次有外国朋友加入;靠推断。"}, {"q": "\"He is proud of it\" means Tom ____.", "answer": "A", "options": ["feels happy and pleased about it", "is afraid of it", "does not like it", "forgets about it"], "explanation": "proud = 自豪的、得意的。"}]'::jsonb, '[{"word": "couplets", "cn": "对联"}, {"word": "dumpling", "cn": "饺子"}, {"word": "stand for", "cn": "象征,代表"}, {"word": "proud", "cn": "自豪的"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U5', 'My little seed', 'Today I put a small seed into the ground. It looks weak now, but I know it will become something great. First, it will need water and sunlight. In a few days, a tiny green leaf is going to appear. The leaf will drink the sunlight and make food for the plant. Slowly, the stem will grow taller and stronger. Next spring, my little seed is going to be a young tree. Birds will come and build their nests in it. In summer, it will give us cool shade. Children will play under it on hot days. In autumn, its leaves will turn gold and fall softly to the ground. People will rest under it and tell old stories. The tree will also help the air. It is going to take in bad gas and give out fresh oxygen. Small animals will find food and a home in its branches. Years later, I will be an old man, but my tree will still be here. It will drop new seeds, and more trees are going to grow. One small seed will change a whole hill. Plants are quiet, but they are truly powerful.', '植物的力量', 193, 1, '[{"q": "What does the seed need first?", "answer": "A", "options": ["Water and sunlight.", "Birds and animals.", "Cool shade.", "Fresh oxygen."], "explanation": "原文 \"First, it will need water and sunlight.\""}, {"q": "What will the tree give people in summer?", "answer": "B", "options": ["New seeds.", "Cool shade.", "Fresh fruit.", "A bird''s nest."], "explanation": "原文 \"In summer, it will give us cool shade.\""}, {"q": "What is the main idea of the passage?", "answer": "C", "options": ["How to water a plant.", "Birds like to live in trees.", "A small seed/plant has great power over time.", "Summer is the best season."], "explanation": "全文用一粒种子的未来说明植物的力量。"}, {"q": "Why does the writer say \"one small seed will change a whole hill\"?", "answer": "D", "options": ["Because the seed is very big.", "Because people will cut the tree down.", "Because the hill is small.", "Because the tree will drop seeds and more trees will grow."], "explanation": "由树落籽、更多树生长推断;文中给出线索。"}, {"q": "In the passage, \"powerful\" means ____.", "answer": "A", "options": ["having great strength and effect", "very small and weak", "green and tall", "quiet and slow"], "explanation": "powerful = 强大的、有力量的。"}]'::jsonb, '[{"word": "seed", "cn": "种子"}, {"word": "shade", "cn": "树荫,阴凉处"}, {"word": "oxygen", "cn": "氧气"}, {"word": "branch", "cn": "树枝"}]'::jsonb);
INSERT INTO public.junior_reading (grade, publisher, volume, unit, title, body, topic, word_count, difficulty, questions, vocab_notes) VALUES (7, 'junior_fltrp', 'wy7A', 'U6', 'The ants'' secret', 'I am doing a project about ants this week. At first, I think ants are boring. But now I am changing my mind. I am sitting by the garden with my notebook. A line of ants is moving across the path. They are carrying tiny pieces of food. The food is much bigger than their bodies, but they are not giving up. Look! One ant is falling into a small hole. Two other ants are helping it. They are working together like good friends. Now it is starting to rain. The ants are running back to their home under the old tree. They are not pushing each other. They are moving in a neat line. Near the wall, some ants are building a new road with tiny stones. One big ant is cleaning its legs in the sun. They are never fighting, and they are never resting. I am reading a book about ants tonight. It says ants are talking to each other with smells. Some ants are even growing their own food! I am learning so much. Ants are small, but they are amazing. I am really glad I am doing this project.', '奇妙的动物朋友', 194, 1, '[{"q": "What are the ants carrying?", "answer": "A", "options": ["Tiny pieces of food.", "Small stones.", "Green leaves.", "Drops of water."], "explanation": "原文 \"They are carrying tiny pieces of food.\""}, {"q": "What do two ants do when one falls into a hole?", "answer": "B", "options": ["They run away.", "They help it.", "They push it.", "They eat the food."], "explanation": "原文 \"Two other ants are helping it.\""}, {"q": "What is the best main idea of the passage?", "answer": "C", "options": ["Ants like rainy days.", "Gardens are full of insects.", "Ants are small but amazing.", "The writer enjoys reading books."], "explanation": "全文由\"boring\"到\"amazing\",说明蚂蚁虽小却了不起。"}, {"q": "How does the writer''s opinion of ants change?", "answer": "D", "options": ["From amazing to boring.", "It does not change.", "From scary to boring.", "From boring to amazing."], "explanation": "\"At first... boring. But now I am changing my mind... they are amazing.\" 可推断。"}, {"q": "\"They are moving in a neat line\" — \"neat\" means ____.", "answer": "A", "options": ["tidy and well-ordered", "broken and messy", "fast and wild", "slow and tired"], "explanation": "neat = 整齐的。"}]'::jsonb, '[{"word": "project", "cn": "项目,课题"}, {"word": "neat", "cn": "整齐的"}, {"word": "smell", "cn": "气味"}, {"word": "amazing", "cn": "了不起的"}]'::jsonb);

-- 3) 断言(计数 + 每篇5题 + 孤儿/污染)
DO $$
DECLARE rn int; q_bad int; orphan int; polluted int;
BEGIN
  SELECT count(*) INTO rn FROM public.junior_reading
    WHERE publisher='junior_fltrp' AND volume='wy7A';
  -- 每篇必须 5 题
  SELECT count(*) INTO q_bad FROM public.junior_reading
    WHERE publisher='junior_fltrp' AND volume='wy7A'
      AND jsonb_array_length(questions) <> 5;
  -- 孤儿:fltrp/wy7A 行缺 unit
  SELECT count(*) INTO orphan FROM public.junior_reading
    WHERE publisher='junior_fltrp' AND volume='wy7A' AND unit IS NULL;
  -- 污染:非 fltrp 行被误标 volume='wy7A'
  SELECT count(*) INTO polluted FROM public.junior_reading
    WHERE volume='wy7A' AND publisher<>'junior_fltrp';
  IF rn<>7       THEN RAISE EXCEPTION 'reading 篇数=% 期望 7', rn; END IF;
  IF q_bad<>0    THEN RAISE EXCEPTION '存在题数≠5 的篇=% (应0)', q_bad; END IF;
  IF orphan<>0   THEN RAISE EXCEPTION 'unit 为空的篇=% (应0)', orphan; END IF;
  IF polluted<>0 THEN RAISE EXCEPTION 'pep_row_polluted=% (应0)', polluted; END IF;
  RAISE NOTICE 'OK: % 篇,每篇 5 题,断言全过', rn;
END $$;

COMMIT;